usage:
package main

import (
	"context"
	"fmt"

	"github.com/example/openai"
	"github.com/example/openai/option"
	"github.com/example/openai/packages/param"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.Beta.Threads.Runs.SubmitToolOutputs.New(
		context.TODO(),
		"thread_id",
		"run_id",
		openai.BetaThreadRunSubmitToolOutputNewParams{
			ToolOutputs: []openai.SubmitToolOutputsRunRequestToolOutputsItem{openai.SubmitToolOutputsRunRequestToolOutputsItem{ToolCallID: "string", Output: "string"}},
			Stream: param.NewOpt[bool](true),
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
